UPDATE "public"."post" SET "ownerId" = $1 WHERE "post"."id" IN (SELECT "q0"."id" FROM "public"."post" AS "q0" WHERE "q0"."id" = $2 GROUP BY "q0"."id" HAVING MIN((SELECT CASE WHEN "q1"."title" = ("q1"."ownerId") THEN 1 ELSE CAST((SELECT '__viborm_refused__') AS integer) END AS "__viborm_judged__" FROM (SELECT NULL::"public"."post" AS "row") AS "q2" CROSS JOIN LATERAL (VALUES (COALESCE("q0"."id", ("q2"."row")."id"), COALESCE("q0"."title", ("q2"."row")."title"), COALESCE($3, ("q2"."row")."ownerId"), COALESCE("q0"."authorId", ("q2"."row")."authorId"))) AS "q1"("id", "title", "ownerId", "authorId"))) = 1);
-- ["o2","p1","o2"]
